mkdir -p /tmp/verify_c4 && cat > /tmp/verify_c4/stock.py << 'EOF'
"""Tiny inventory ledger (eval fixture)."""
from dataclasses import dataclass, field


@dataclass
class Item:
    sku: str
    qty: int
    price_cents: int


@dataclass
class Ledger:
    items: dict = field(default_factory=dict)

    def add(self, sku: str, qty: int, price_cents: int) -> None:
        if sku in self.items:
            self.items[sku].qty += qty
        else:
            self.items[sku] = Item(sku, qty, price_cents)

    def remove(self, sku: str, qty: int) -> None:
        item = self.items[sku]
        item.qty -= qty

    def total_value_cents(self) -> int:
        return sum(i.qty * i.price_cents for i in self.items.values())

    def low_stock(self, threshold: int) -> list:
        return [i.sku for i in self.items.values() if i.qty < threshold]
EOF
cat > /tmp/verify_c4/test_c4.py << 'EOF'
from stock import Ledger

l = Ledger()
try:
    l.remove("MISSING-SKU", 5)
    print("NO EXCEPTION RAISED")
except KeyError as e:
    print("KeyError raised:", repr(e))
except ValueError as e:
    print("ValueError raised:", repr(e))

print("---")
# Also confirm the qty-exceeds-stock case does raise ValueError per spec (or does it?)
l2 = Ledger()
l2.add("SKU1", 3, 100)
try:
    l2.remove("SKU1", 10)
    print("NO EXCEPTION RAISED for qty exceeding stock; item.qty =", l2.items["SKU1"].qty)
except ValueError as e:
    print("ValueError raised for exceeding stock:", repr(e))
except KeyError as e:
    print("KeyError raised for exceeding stock:", repr(e))
EOF
cd /tmp/verify_c4 && python3 test_c4.py

